  return {'baseline_RMSE':rmse(old),'candidate_RMSE':rmse(new),'gain':gain,'fold_control_RMSE':fa,'fold_huber_RMSE':fb,'fold_gains':fg,'positive_folds':sum(v>0 for v in fg),'conditional_CI95':np.quantile(boots,[.025,.975]).tolist(),'top5_removed_gain':float(np.sqrt(ae[keep].mean())-np.sqrt(be[keep].mean())),'top5_removed_IDs':z['ids'][order[-5:]].tolist(),'positive_IDs':int(np.sum(delta>0)),'prediction_delta_RMS':float(np.sqrt(np.mean((new-old)**2)))}
